	@Test
	void fullLegacyHotPackMigratesToColdWithoutChangingCommittedHistory(@TempDir Path directory) throws Exception {
		try (Fixture fixture = new Fixture(directory)) {
			fixture.commit(fixedLegacyControl(0));
			fixture.awaitPublisher();
			byte[] initialCatalog = catalog(fixture.triples());
			byte[] initialFrame = frames(LmdbBackupCatalogTestSupport.unpack(initialCatalog))
					.values()
					.iterator()
					.next();
			int frameBytes = initialFrame.length;
			assertEquals(94, LmdbBackupChunkCodec.decodedLength(initialFrame, frameBytes, true),
					"The real legacy control must stay below both small-chunk compression thresholds");
			assertEquals(0, initialFrame[4], "The fixed-width legacy control must remain an actual raw frame");
			int legacyLimit = fixture.triples().getTxnManager().doWithFreshPriority((stack, transaction) -> {
				MDBStat stats = MDBStat.malloc(stack);
				E(mdb_stat(transaction, database(stack, transaction, null), stats));
				return stats.ms_psize() / 2 - 128;
			});
			int count = (legacyLimit - 12) / (12 + frameBytes);
			while (fixture.expected.size() < count) {
				fixture.commit(fixedLegacyControl(fixture.expected.size()));
			}
			Map<Long, byte[]> actualFrames = sourceFrames(fixture.triples());
			assertEquals(fixture.expected.keySet(), actualFrames.keySet());
			for (byte[] frame : actualFrames.values()) {
				assertEquals(frameBytes, frame.length,
						"Every actual legacy control must have the measured fixed width");
				assertEquals(0, frame[4]);
			}
			byte[] legacyPack = pack(actualFrames);
			assertTrue(legacyPack.length > LmdbBackupCatalogTestSupport.packCapacity(initialCatalog.length));
			assertTrue(legacyPack.length <= legacyLimit && legacyPack.length + 12 + frameBytes > legacyLimit,
					"The upgrade fixture must exercise a complete old-size pack that the catalog cannot hold");
			long head = fixture.head();
			// Rehouse only bytes extracted from real public commits in the exact previous native layout.
			// Logical identities, source records and publication acknowledgements are not synthesized.
			mutate(fixture.triples(), (stack, transaction) -> {
				E(mdb_del(transaction, database(stack, transaction, null),
						MDBVal.malloc(stack).mv_data(stack.bytes(LmdbBackupCatalogTestSupport.KEY)), null));
				for (var row : LmdbBackupOutboxPackTest.coldRows(stack, transaction)) {
					E(mdb_del(transaction, database(stack, transaction, row.database()),
							MDBVal.malloc(stack).mv_data(stack.bytes(row.key())), null));
				}
				put(stack, transaction, HOT, HOT_KEY, legacyPack);
			});
			assertNull(catalog(fixture.triples()));
			fixture.assertSources(fixture.store);
			fixture.closeStore();
			LegacyStoreDiscovery.verify(fixture.live.toFile(), properties(fixture.live));
			LmdbStore reopened = new LmdbStore(fixture.live.toFile(), fixture.config);
			reopened.init();
			try {
				TripleStore triples = reopened.getBackingStore().getTripleStore();
				assertTrue(frames(LmdbBackupCatalogTestSupport.unpack(catalog(triples))).isEmpty());
				byte[] migrated = triples.getTxnManager()
						.doWithFreshPriority(
								(stack, transaction) -> LmdbBackupOutboxPackTest.coldPack(stack, transaction, head));
				assertArrayEquals(legacyPack, migrated,
						"Initialization must preserve the complete old-size hot pack byte for byte in cold storage");
				assertTrue(frames(triples.getTxnManager()
						.doWithFreshPriority((stack, transaction) -> get(stack, transaction, HOT, HOT_KEY))).isEmpty());
				fixture.assertSources(reopened);
				fixture.commit(reopened, fixedLegacyControl(count));
				assertEquals(List.of(head + 1),
						new ArrayList<>(frames(LmdbBackupCatalogTestSupport.unpack(catalog(triples))).keySet()));
				assertEquals(head + 1, reopened.getBackupService()
						.createBackup(BackupRequest.builder(fixture.backups, BackupType.INCREMENTAL)
								.sinceTransactionId(fixture.baseline)
								.build())
						.getEndTransactionId());
				fixture.assertArchives(reopened, directory.resolve("migration-export"));
			} finally {
				reopened.shutDown();
			}
		}
	}

	@Test
	void childReservationDoesNotEscapeAnAbortedParent(@TempDir Path directory) throws Exception {
		try (Fixture fixture = new Fixture(directory)) {
			assertTrue(frames(LmdbBackupCatalogTestSupport.unpack(catalog(fixture.triples()))).isEmpty());
			mutate(fixture.triples(), (stack, transaction) -> E(mdb_del(transaction,
					database(stack, transaction, null),
					MDBVal.malloc(stack).mv_data(stack.bytes(LmdbBackupCatalogTestSupport.KEY)), null)));
			assertNull(catalog(fixture.triples()));
			try (LmdbBackupOutbox outbox = fixture.triples()
					.getTxnManager()
					.doWithFreshPriority(LmdbBackupCatalogIntegrityTest::outbox)) {
				AtomicBoolean reserved = new AtomicBoolean();
				assertThrows(SailException.class, () -> mutate(fixture.triples(), (stack, transaction) -> {
					assertTrue(outbox.initializeCatalog(mdb_txn_env(transaction), transaction));
					assertNotNull(LmdbBackupCatalogTestSupport.read(stack, transaction));
					reserved.set(true);
					throw new SailException("Abort parent after its reservation child committed");
				}));
				assertTrue(reserved.get());
				assertNull(catalog(fixture.triples()), "An aborted parent must retire its child's reservation");
				mutate(fixture.triples(), (stack,
						transaction) -> assertTrue(outbox.initializeCatalog(mdb_txn_env(transaction), transaction)));
				assertNotNull(catalog(fixture.triples()), "The same outbox must retry from actual native presence");
			}
			fixture.commit(small(0));
			fixture.awaitPublisher();
			fixture.assertSources(fixture.store);
			fixture.drainAndAssertArchives();
		}
	}

	@Test
	void catalogRollbackAndRealCapacityReplayPreserveTheSourceChain(@TempDir Path directory) throws Exception {
		try (Fixture fixture = new Fixture(directory)) {
			fixture.commit(small(0));
			fixture.awaitPublisher();
			byte[] retained = catalog(fixture.triples());
			long next = fixture.head() + 1;
			AtomicBoolean staged = new AtomicBoolean();
			fixture.triples().beforePhysicalCommitForTest = () -> {
				try (MemoryStack stack = MemoryStack.stackPush()) {
					assertTrue(frames(LmdbBackupCatalogTestSupport.unpack(
							LmdbBackupCatalogTestSupport.read(stack, fixture.triples().writeTxn))).containsKey(next));
					staged.set(true);
				} catch (IOException failure) {
					throw new UncheckedIOException(failure);
				}
				throw new SailException("Abort after the actual catalog stage was written");
			};
			try {
				assertThrows(SailException.class, () -> add(fixture.store, small(1)));
			} finally {
				fixture.triples().beforePhysicalCommitForTest = null;
			}
			assertTrue(staged.get());
			assertArrayEquals(retained, catalog(fixture.triples()));
			assertEquals(next - 1, fixture.head());
			assertNull(fixture.triples().readBackupStageHeader(next));
			fixture.commit(small(1));
			long dictionaryMap = fixture.store.getBackingStore().valueStore().replayMapSize();
			fixture.observePreparation.set(true);
			fixture.commit(statement("large", entropy(2 * 1024 * 1024)));
			fixture.observePreparation.set(false);
			assertTrue(fixture.preparationMap.get() > 0);
			assertTrue(fixture.triples().mapSizeBytes() > fixture.preparationMap.get(),
					"A real large public record must force source capacity replay after catalog history exists");
			assertEquals(dictionaryMap, fixture.store.getBackingStore().valueStore().replayMapSize());
			LmdbBackupFallbackTestSupport.assertStripedFrame(fixture.triples(), fixture.head());
			assertTrue(frames(LmdbBackupCatalogTestSupport.unpack(catalog(fixture.triples()))).isEmpty());
			fixture.commit(small(3));
			assertEquals(List.of(fixture.head()),
					new ArrayList<>(frames(LmdbBackupCatalogTestSupport.unpack(catalog(fixture.triples()))).keySet()));
			fixture.assertSources(fixture.store);
			fixture.drainAndAssertArchives();
		}
	}

	@ParameterizedTest
	@ValueSource(strings = { "short", "long", "magic", "used-short", "used-long", "padding", "pack-crc",
			"frame-crc" })
	void malformedCatalogEnvelopeOrInnerFrameIsRejected(String corruption, @TempDir Path directory) throws Exception {
		try (Fixture fixture = new Fixture(directory)) {
			fixture.commit(small(0));
			fixture.awaitPublisher();
			byte[] changed = catalog(fixture.triples());
			switch (corruption) {
			case "short" -> changed = Arrays.copyOf(changed, changed.length - 1);
			case "long" -> changed = Arrays.copyOf(changed, changed.length + 1);
			case "magic" -> ByteBuffer.wrap(changed).putInt(0, 0);
			case "used-short" -> ByteBuffer.wrap(changed).putInt(4, 11);
			case "used-long" -> ByteBuffer.wrap(changed)
					.putInt(4, LmdbBackupCatalogTestSupport.packCapacity(changed.length) + 1);
			case "padding" -> changed[changed.length - 1] = 1;
			case "pack-crc" -> changed[8 + ByteBuffer.wrap(changed).getInt(4) - 1] ^= 1;
			case "frame-crc" -> {
				byte[] inner = LmdbBackupCatalogTestSupport.unpack(changed);
				inner[20 + ByteBuffer.wrap(inner).getInt(16) - 1] ^= 1;
				checksum(inner);
				changed = LmdbBackupCatalogTestSupport.wrap(inner, changed.length);
			}
			default -> throw new AssertionError(corruption);
			}
			byte[] corrupted = changed;
			mutate(fixture.triples(),
					(stack, transaction) -> put(stack, transaction, null, LmdbBackupCatalogTestSupport.KEY, corrupted));
			assertThrows(IOException.class, () -> fixture.triples().readBackupStageHeader(fixture.head()));
			assertThrows(IOException.class, () -> {
				try (var input = fixture.triples().openBackupStage(fixture.head())) {
					input.readAllBytes();
				}
			});
			fixture.closeStore();
			assertThrows(IOException.class, () -> LegacyStoreDiscovery.verify(fixture.live.toFile(),
					properties(fixture.live)));
			LmdbStore broken = new LmdbStore(fixture.live.toFile(), config(false));
			assertThrows(SailException.class, broken::init,
					"Disabling publication must not bypass persisted-source integrity validation");
		}
	}

